2	
3	import com.example.order.product.ProductNotFoundException;
4	import com.fasterxml.jackson.databind.JsonMappingException;
5	import java.net.URI;
6	import java.util.Comparator;
7	import java.util.List;
8	import java.util.Map;
9	import org.slf4j.Logger;
10	import org.slf4j.LoggerFactory;
11	import org.springframework.beans.TypeMismatchException;
12	import org.springframework.http.HttpHeaders;
13	import org.springframework.http.HttpStatus;
14	import org.springframework.http.HttpStatusCode;
15	import org.springframework.http.MediaType;
16	import org.springframework.http.ProblemDetail;
17	import org.springframework.http.ResponseEntity;
18	import org.springframework.http.converter.HttpMessageNotReadableException;
19	import org.springframework.lang.Nullable;
20	import org.springframework.validation.FieldError;
21	import org.springframework.validation.ObjectError;
22	import org.springframework.web.bind.MethodArgumentNotValidException;
23	import org.springframework.web.bind.annotation.ExceptionHandler;
24	import org.springframework.web.bind.annotation.RestControllerAdvice;
25	import org.springframework.web.context.request.ServletWebRequest;
26	import org.springframework.web.context.request.WebRequest;
27	import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;
28	
29	/**
30	 * 모든 에러를 RFC 9457 application/problem+json 으로 매핑한다 (01_api_design.md §4).
31	 * Accept 협상에 의존하지 않도록 Content-Type 을 명시 지정한다.
32	 */
33	@RestControllerAdvice
34	public class GlobalExceptionHandler extends ResponseEntityExceptionHandler {
35	
36	    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);
37	
38	    private static final String DETAIL_VALIDATION = "요청 본문 검증에 실패했습니다.";
39	    private static final String DETAIL_MALFORMED_GENERIC = "요청 본문을 읽을 수 없습니다. 올바른 JSON 형식인지 확인하세요.";
40	    private static final String DETAIL_UNEXPECTED = "예상치 못한 오류가 발생했습니다.";
41	
42	    private static final Comparator<Map<String, String>> ERROR_ORDER =
43	            Comparator.<Map<String, String>, String>comparing(e -> e.get("field"))
44	                    .thenComparing(e -> e.get("message"));
45	
46	    /** Spring MVC 표준 예외를 포함한 모든 ProblemDetail 응답의 Content-Type 을 problem+json 으로 고정한다. */
47	    @Override
48	    protected ResponseEntity<Object> createResponseEntity(
49	            @Nullable Object body, HttpHeaders headers, HttpStatusCode statusCode, WebRequest request) {
50	        HttpHeaders merged = new HttpHeaders();
51	        merged.putAll(headers);
52	        if (body instanceof ProblemDetail) {
53	            merged.setContentType(MediaType.APPLICATION_PROBLEM_JSON);
54	        }
55	        return new ResponseEntity<>(body, merged, statusCode);
56	    }
57	
58	    @Override
59	    protected ResponseEntity<Object> handleMethodArgumentNotValid(
60	            MethodArgumentNotValidException ex, HttpHeaders headers, HttpStatusCode status, WebRequest request) {
61	        List<Map<String, String>> errors = ex.getBindingResult().getAllErrors().stream()
62	                .map(GlobalExceptionHandler::toError)
63	                .sorted(ERROR_ORDER)
64	                .toList();
65	
66	        ProblemDetail pd = problem(HttpStatus.BAD_REQUEST, ProblemTypes.VALIDATION_FAILED,
67	                ProblemTypes.TITLE_VALIDATION_FAILED, DETAIL_VALIDATION, request);
68	        pd.setProperty("errors", errors);
69	        return createResponseEntity(pd, headers, HttpStatus.BAD_REQUEST, request);
70	    }
71	
72	    @Override
73	    protected ResponseEntity<Object> handleHttpMessageNotReadable(
74	            HttpMessageNotReadableException ex, HttpHeaders headers, HttpStatusCode status, WebRequest request) {
75	        String field = extractFieldName(ex);
76	        String detail = field != null
77	                ? "필드 '" + field + "'의 값 형식이 올바르지 않습니다."
78	                : DETAIL_MALFORMED_GENERIC;
79	        ProblemDetail pd = problem(HttpStatus.BAD_REQUEST, ProblemTypes.MALFORMED_REQUEST_BODY,
80	                ProblemTypes.TITLE_MALFORMED_REQUEST_BODY, detail, request);
81	        return createResponseEntity(pd, headers, HttpStatus.BAD_REQUEST, request);
82	    }
83	
84	    @Override
85	    protected ResponseEntity<Object> handleTypeMismatch(
86	            TypeMismatchException ex, HttpHeaders headers, HttpStatusCode status, WebRequest request) {
87	        String name = ex.getPropertyName() != null ? ex.getPropertyName() : "";
88	        ProblemDetail pd = problem(HttpStatus.BAD_REQUEST, ProblemTypes.INVALID_PATH_PARAMETER,
89	                ProblemTypes.TITLE_INVALID_PATH_PARAMETER, "경로 변수 '" + name + "'는 정수여야 합니다.", request);
90	        return createResponseEntity(pd, headers, HttpStatus.BAD_REQUEST, request);
91	    }
92	
93	    @ExceptionHandler(ProductNotFoundException.class)
94	    public ResponseEntity<Object> handleProductNotFound(ProductNotFoundException ex, WebRequest request) {
95	        ProblemDetail pd = problem(HttpStatus.NOT_FOUND, ProblemTypes.PRODUCT_NOT_FOUND,
96	                ProblemTypes.TITLE_PRODUCT_NOT_FOUND, ex.getMessage(), request);
97	        return createResponseEntity(pd, new HttpHeaders(), HttpStatus.NOT_FOUND, request);
98	    }
99	
100	    @ExceptionHandler(Exception.class)
101	    public ResponseEntity<Object> handleUnexpected(Exception ex, WebRequest request) {
102	        log.error("Unexpected error", ex);
103	        ProblemDetail pd = problem(HttpStatus.INTERNAL_SERVER_ERROR, URI.create("about:blank"),
104	                ProblemTypes.TITLE_INTERNAL_SERVER_ERROR, DETAIL_UNEXPECTED, request);
105	        return createResponseEntity(pd, new HttpHeaders(), HttpStatus.INTERNAL_SERVER_ERROR, request);
106	    }
107	
108	    private static ProblemDetail problem(
109	            HttpStatus status, URI type, String title, String detail, WebRequest request) {
110	        ProblemDetail pd = ProblemDetail.forStatusAndDetail(status, detail);
111	        pd.setType(type);
112	        pd.setTitle(title);
113	        if (request instanceof ServletWebRequest swr) {
114	            pd.setInstance(URI.create(swr.getRequest().getRequestURI()));
115	        }
116	        return pd;
117	    }
118	
119	    private static Map<String, String> toError(ObjectError error) {
120	        String field = error instanceof FieldError fe ? fe.getField() : error.getObjectName();
121	        String message = error.getDefaultMessage() != null ? error.getDefaultMessage() : "";
122	        return Map.of("field", field, "message", message);
123	    }
124	
125	    @Nullable
126	    private static String extractFieldName(Throwable ex) {
127	        for (Throwable t = ex; t != null; t = t.getCause()) {
128	            if (t instanceof JsonMappingException jme && !jme.getPath().isEmpty()) {
129	                String name = jme.getPath().get(jme.getPath().size() - 1).getFieldName();
130	                if (name != null) {
131	                    return name;
132	                }
133	            }
134	            if (t.getCause() == t) {
135	                break;
136	            }
137	        }
138	        return null;
139	    }
140	}
